            padding: '8px 16px',
            fontWeight: 600,
            fontSize: 14,
          }}
        >
          <span
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
            }}
          >
            <Icon data={collapsed ? CaretRight : CaretDown} size={14} />
            <span
              style={{
                display: 'inline-block',
                width: 10,
                height: 10,
                borderRadius: '50%',
                background: color,
                flexShrink: 0,
              }}
            />
            <span>{status}</span>
            <span
              style={{
                fontWeight: 400,
                color: 'var(--g-color-text-secondary)',
                fontSize: 13,
              }}
            >
              ({count})
            </span>
          </span>
        </td>
      </tr>
    );
  };

  // Custom table rendering
  return (
    <div>
