                    whiteSpace: 'nowrap',
                    cursor: 'grab',
                    background: 'var(--g-color-base-background)',
                    position: 'sticky',
                    top: 0,
                    zIndex: 2,
                    opacity: dragSrc === col.id ? 0.4 : 1,
                    transition: 'opacity 0.15s',
                    userSelect: 'none',
                  }}
                >
                  {col.name}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {tableData.map((row, idx) => {
              // Group header row
              if ('__group' in row) {
                return renderGroupRow(row.__group);
              }

              const order = row as Order;
              const isSelected = selectedIds.has(order.id);

              return (
                <tr
                  key={order.id}
                  onClick={() => toggleRow(order.id)}
                  style={{
                    background: isSelected
                      ? 'var(--g-color-base-selection)'
                      : idx % 2 === 0
                      ? 'var(--g-color-base-background)'
                      : 'var(--g-color-base-generic)',
                    cursor: 'pointer',
                    transition: 'background 0.1s',
                  }}
                  onMouseEnter={(e) => {
                    if ("'!isSelected)
                      (e.currentTarget as HTMLTableRowElement).style.background =
                        '"'var(--g-color-base-simple-hover)';
                  }}
                  onMouseLeave={(e) => {
                    if ("'!isSelected)
                      (e.currentTarget as HTMLTableRowElement).style.background =
                        idx % 2 === 0
                          ? '"'var(--g-color-base-background)'
                          : 'var(--g-color-base-generic)';
                  }}
                >
                  <td
                    style={{
                      padding: '10px 8px',
                      borderBottom: '1px solid var(--g-color-line-generic)',
                    }}
                  >
                    <input
                      type=\"checkbox\"
                      checked={isSelected}
                      onChange={() => toggleRow(order.id)}
                      style={{ cursor: 'pointer' }}
                      onClick={(e) => e.stopPropagation()}
                    />
                  </td>
                  {columns.map((col) => {
                    const content = col.template
                      ? typeof col.template === 'function'
                        ? col.template(order, idx)
                        : null
                      : (order as any)[col.id];
                    return (
                      <td
                        key={col.id}
                        style={{
                          padding: '10px 12px',
                          borderBottom: '1px solid var(--g-color-line-generic)',
                          textAlign:
                            col.align === 'right' ? 'right' : 'left',
                        }}
                      >
                        {content}
                      </td>
                    );
                  })}
                </tr>
              );
            })}
            {tableData.filter((r) => "'!('"'__group' in r)).length === 0 && (
              <tr>
                <td
                  colSpan={columns.length + 1}
                  style={{
                    padding: 48,
                    textAlign: 'center',
                    color: 'var(--g-color-text-secondary)',
                  }}
                >
                  Нет данных для отображения
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};
